static int classification(const sf::Map&m,const sf::RealBounds&bound,const std::vector<Site>&sites){
    S image[2];for(int k=0;k<2;k++){Q lo=sf::lower(m.vertex[0][k]),hi=sf::upper(m.vertex[0][k]);for(int a=1;a<3;a++){lo=std::min(lo,sf::lower(m.vertex[a][k]));hi=std::max(hi,sf::upper(m.vertex[a][k]));}image[k]=sf::range(lo,hi);image[k].e=sf::add(image[k].e,bound.displacement[k]);}auto own=std::find_if(sites.begin(),sites.end(),[](const Site&s){return s.id==68526;});need(own!=sites.end(),"same target68526");bool inside=true;for(auto&other:sites)if(other.id!=own->id){S n[2]={other.p[0]-own->p[0],other.p[1]-own->p[1]},f=n[0]*(image[0]-own->p[0])+n[1]*(image[1]-own->p[1])-(n[0]*n[0]+n[1]*n[1]+own->w-other.w)/S(2);if(sf::lower(f)>0)return 0;inside=inside&&sf::upper(f)<0;}return inside?1:2;
}
